# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TARIM DEVRİMİ (NEOLİTİK ÇAĞ): TÜKETİCİLİKTEN ÜRETİCİ YAŞAMA GEÇİŞ</text>\n  <rect x="20" y="45" width="300" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="170" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">TARIM DEVRİMİ ÖNCESİ (PALEOLİTİK)</text>\n  <text x="35" y="92" font-size="11" font-weight="bold" fill="#78350f">• Ekonomi: Tüketici (Avcı ve Toplayıcı)</text>\n  <text x="35" y="114" font-size="11" fill="#92400e">• Yaşam Tarzı: Konargöçer (Mevsimlik göç)</text>\n  <text x="35" y="136" font-size="11" fill="#92400e">• Barınma: Doğal mağaralar ve kaya sığınakları</text>\n  <text x="35" y="158" font-size="11" fill="#92400e">• Araç-Gereç: Kaba yontma taş ve kemik aletler</text>\n  <text x="35" y="180" font-size="11" fill="#92400e">• Üretim Fazlası: Depolama ve artı ürün yok</text>\n  <text x="35" y="202" font-size="11" fill="#92400e">• Toplum: Küçük, eşitlikçi avcı klanları</text>\n  <text x="35" y="224" font-size="10.5" font-weight="bold" fill="#b91c1c">→ Doğaya ve iklim koşullarına tam bağımlılık</text>\n  <polygon points="326,135 352,135 352,125 370,142 352,159 352,149 326,149" fill="#16a34a"/>\n  <text x="348" y="118" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#15803d">MÖ 10.000</text>\n  <rect x="378" y="45" width="302" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="529" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">TARIM DEVRİMİ SONRASI (NEOLİTİK)</text>\n  <text x="393" y="92" font-size="11" font-weight="bold" fill="#14532d">• Ekonomi: Üretici (Tarım ve Hayvancılık)</text>\n  <text x="393" y="114" font-size="11" fill="#166534">• Yaşam Tarzı: Su kenarlarında yerleşik yaşam</text>\n  <text x="393" y="136" font-size="11" fill="#166534">• Barınma: Kerpiç ve taş kalıcı köy/kent evleri</text>\n  <text x="393" y="158" font-size="11" fill="#166534">• Araç-Gereç: Orak, öğütme taşı, çanak çömlek</text>\n  <text x="393" y="180" font-size="11" fill="#166534">• Üretim Fazlası: Artı ürün (surplus) ve ambarlar</text>\n  <text x="393" y="202" font-size="11" fill="#166534">• Toplum: İş bölümü, özel mülkiyet ve sınıflar</text>\n  <text x="393" y="224" font-size="10.5" font-weight="bold" fill="#15803d">→ Bereketli Hilal\'de yerleşik medeniyetin doğuşu</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BEREKETLİ HİLAL VE ANADOLU\'DAKİ ÖNCÜ NEOLİTİK MERKEZLER</text>\n  <rect x="20" y="45" width="215" height="195" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="127" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">1. GÖBEKLİTEPE (Şanlıurfa)</text>\n  <text x="32" y="90" font-size="10.5" font-weight="bold" fill="#713f12">• Dönem: MÖ 10.000 (Neolitik A)</text>\n  <text x="32" y="112" font-size="10.5" fill="#713f12">• Önemi: İnsanlık tarihinin bilinen</text>\n  <text x="40" y="127" font-size="10.5" font-weight="bold" fill="#b91c1c">en eski anıtsal tapınak merkezi.</text>\n  <text x="32" y="149" font-size="10.5" fill="#713f12">• Mimari: T biçimli dikilitaşlar ve</text>\n  <text x="40" y="164" font-size="10.5" fill="#713f12">kabartma hayvan figürleri.</text>\n  <text x="32" y="186" font-size="10.5" fill="#713f12">• Kanıt: Dini inancın yerleşik</text>\n  <text x="40" y="201" font-size="10.5" fill="#713f12">yaşama ve tarıma geçişi</text>\n  <text x="40" y="216" font-size="10.5" fill="#713f12">tetiklediğini ortaya koymuştur.</text>\n  <rect x="243" y="45" width="214" height="195" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">2. ÇAYÖNÜ (Diyarbakır)</text>\n  <text x="255" y="90" font-size="10.5" font-weight="bold" fill="#064e3b">• Dönem: MÖ 8500 - 7000</text>\n  <text x="255" y="112" font-size="10.5" fill="#064e3b">• Önemi: Yakın Doğu ve Avrupa\'da</text>\n  <text x="263" y="127" font-size="10.5" font-weight="bold" fill="#047857">ilk tarımsal köy yerleşmesi.</text>\n  <text x="255" y="149" font-size="10.5" fill="#064e3b">• Üretim: Yabani buğday (emmer)</text>\n  <text x="263" y="164" font-size="10.5" fill="#064e3b">ıslah edildi, koyun-keçi beslendi.</text>\n  <text x="255" y="186" font-size="10.5" fill="#064e3b">• Teknoloji: Izgara planlı evler</text>\n  <text x="263" y="201" font-size="10.5" fill="#064e3b">ve doğal bakırın (malakit)</text>\n  <text x="263" y="216" font-size="10.5" fill="#064e3b">tavlanarak dövüldüğü ilk yer.</text>\n  <rect x="465" y="45" width="215" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="572" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">3. ÇATALHÖYÜK (Konya)</text>\n  <text x="477" y="90" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Dönem: MÖ 7400 - 6200</text>\n  <text x="477" y="112" font-size="10.5" fill="#1e3a8a">• Önemi: İnsanlığın ilk büyük</text>\n  <text x="485" y="127" font-size="10.5" font-weight="bold" fill="#1d4ed8">kentsel mimari dokularından biri.</text>\n  <text x="477" y="149" font-size="10.5" fill="#1e3a8a">• Mimari: Sokaksız, bitişik kerpiç</text>\n  <text x="485" y="164" font-size="10.5" fill="#1e3a8a">evler; çatıdan merdivenli giriş.</text>\n  <text x="477" y="186" font-size="10.5" fill="#1e3a8a">• Ekonomi &amp; Sanat: Duvar resmi,</text>\n  <text x="485" y="201" font-size="10.5" fill="#1e3a8a">Ana Tanrıça figürini ve</text>\n  <text x="485" y="216" font-size="10.5" fill="#1e3a8a">obsidiyen (volkanik cam) ticareti.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ARTI ÜRÜNÜN (SURPLUS) EKONOMİ VE TOPLUMSAL YAPIYA ETKİ ZİNCİRİ</text>\n  <rect x="18" y="50" width="150" height="185" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="93" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#14532d">1. TARIMSAL VERİM</text>\n  <text x="30" y="98" font-size="10" fill="#166534">• Sulama kanalları</text>\n  <text x="30" y="118" font-size="10" fill="#166534">• Saban ve hayvan gücü</text>\n  <text x="30" y="138" font-size="10" fill="#166534">• Toprağın düzenli ekimi</text>\n  <text x="30" y="158" font-size="10" fill="#166534">• Beslenme güvenliği</text>\n  <text x="93" y="205" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Hızlı Nüfus Artışı</text>\n  <polygon points="172,135 184,135 184,129 192,139 184,149 184,143 172,143" fill="#15803d"/>\n  <rect x="196" y="50" width="150" height="185" rx="10" fill="#fef9c3" stroke="#ca8a04" stroke-width="2"/>\n  <text x="271" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#854d0e">2. ARTI ÜRÜN</text>\n  <text x="208" y="98" font-size="10" fill="#713f12">• Tüketimden fazla</text>\n  <text x="215" y="113" font-size="10" fill="#713f12">tahıl üretilmesi</text>\n  <text x="208" y="135" font-size="10" fill="#713f12">• Çanak çömlek ve</text>\n  <text x="215" y="150" font-size="10" fill="#713f12">tapınak ambarlarında</text>\n  <text x="215" y="165" font-size="10" fill="#713f12">ürün depolanması</text>\n  <text x="271" y="205" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#a16207">Özel Mülkiyet Doğuşu</text>\n  <polygon points="350,135 362,135 362,129 370,139 362,149 362,143 350,143" fill="#ca8a04"/>\n  <rect x="374" y="50" width="150" height="185" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="449" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">3. İŞ BÖLÜMÜ</text>\n  <text x="386" y="98" font-size="10" fill="#1e3a8a">• Çiftçilik dışı meslekler:</text>\n  <text x="392" y="116" font-size="10" fill="#1e3a8a">- Zanaatkâr (çömlekçi)</text>\n  <text x="392" y="134" font-size="10" fill="#1e3a8a">- Tüccar (mübadele)</text>\n  <text x="392" y="152" font-size="10" fill="#1e3a8a">- Asker ve yönetici</text>\n  <text x="392" y="170" font-size="10" fill="#1e3a8a">- Din adamı (rahip)</text>\n  <text x="449" y="205" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Takas ve Ticaret Ağı</text>\n  <polygon points="528,135 540,135 540,129 548,139 540,149 540,143 528,143" fill="#2563eb"/>\n  <rect x="552" y="50" width="130" height="185" rx="10" fill="#f3e8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="617" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">4. KENT &amp; DEVLET</text>\n  <text x="562" y="98" font-size="10" fill="#581c87">• Sosyal tabakalaşma</text>\n  <text x="562" y="118" font-size="10" fill="#581c87">• Vergi ve kayıt</text>\n  <text x="562" y="138" font-size="10" fill="#581c87">• Hukuk kuralları</text>\n  <text x="562" y="158" font-size="10" fill="#581c87">• Şehir devletleri</text>\n  <text x="617" y="205" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7e22ce">Yazının İcadı</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
